import{_ as t,o as i,c as s,a2 as e}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"MLua и игра","description":"","frontmatter":{},"headers":[],"relativePath":"ru/mlua/environment.md","filePath":"ru/mlua/environment.md","lastUpdated":1789328014000}'),n={name:"ru/mlua/environment.md"};function h(l,a,r,d,p,o){return i(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="mlua-и-игра" tabindex="-1">MLua и игра <a class="header-anchor" href="#mlua-и-игра" aria-label="Permalink to &quot;MLua и игра&quot;">​</a></h1><h2 id="кто-запускает-скрипт" tabindex="-1">Кто запускает скрипт? <a class="header-anchor" href="#кто-запускает-скрипт" aria-label="Permalink to &quot;Кто запускает скрипт?&quot;">​</a></h2><p>Разработчик игры встраивает MangLua в свой проект и определяет доступные скрипты и API. Вы, как автор мода, пишете код на MLua для взаимодействия с этим предоставленным API. Запущенная игра часто называется <strong>хост-приложением</strong>.</p><h2 id="три-уровня-возможностеи" tabindex="-1">Три уровня возможностей <a class="header-anchor" href="#три-уровня-возможностеи" aria-label="Permalink to &quot;Три уровня возможностей&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Уровень</th><th>Что предоставляет</th><th>Чего не предоставляет</th></tr></thead><tbody><tr><td>Виртуальная машина Lua</td><td>Значения, функции, таблицы, корутины и базовые библиотеки</td><td>Доступ ко всем типам игры</td></tr><tr><td>Язык MLua и Prelude</td><td>Классы, модификаторы доступа, перечисления, дженерики и вспомогательные функции</td><td>Автоматические права на патчинг методов или создание компонентов</td></tr><tr><td>Интеграция с игрой</td><td>Зарегистрированные управляемые типы, модули API, привязка компонентов и бэкенд патчинга</td><td>Гарантию работы всех возможностей C# или произвольных соглашений вызова</td></tr></tbody></table><p>Скрипт может использовать ту или иную возможность только тогда, когда присутствуют соответствующие уровни.</p><h2 id="полныи-пример-без-неявных-объектов" tabindex="-1">Полный пример без неявных объектов <a class="header-anchor" href="#полныи-пример-без-неявных-объектов" aria-label="Permalink to &quot;Полный пример без неявных объектов&quot;">​</a></h2><p>Для этого примера игра должна предоставить доступ к <code>GameObject</code> и <code>PrimitiveType</code> из Unity API:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">give UnityEngine</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cube </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GameObject.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">CreatePrimitive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(PrimitiveType.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Cube</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cube.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MLua cube&quot;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cube.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Здесь <code>cube</code> - локальная переменная со ссылкой на объект, возвращённый методом <code>CreatePrimitive</code>. Никаких неявных глобальных переменных вроде <code>host</code> в рантайме не предполагается.</p><h2 id="доступность-функции" tabindex="-1">Доступность функций <a class="header-anchor" href="#доступность-функции" aria-label="Permalink to &quot;Доступность функций&quot;">​</a></h2><p>Перед написанием мода изучите список открытых типов игры и поддерживаемые возможности. Подробнее смотрите в разделах <a href="/ru/mlua/managed-api.html">Работа с Unity и игровым API</a>, <a href="/ru/mlua/injection.html">Инъекция классов</a> и <a href="/ru/mlua/patching.html">Патчинг методов</a>.</p>`,12)])])}const u=t(n,[["render",h]]);export{c as __pageData,u as default};
